CREATE TABLE closed_sessions(session_id TEXT,canonical_id TEXT,tenant_id TEXT,start_time TIMESTAMP,end_time TIMESTAMP,duration_sec BIGINT,event_count BIGINT,pages TEXT[],event_types TEXT[],device_type TEXT,browser TEXT,country TEXT,window_start TIMESTAMP,window_end TIMESTAMP) WITH(connector='single_file',path='@INPUT@',format='json',type='source',wait_for_control='true');
CREATE TABLE result(session_id TEXT,canonical_id TEXT,tenant_id TEXT,start_time TEXT,end_time TEXT,duration_sec BIGINT,event_count BIGINT,pages TEXT[],event_types TEXT[],device_type TEXT,browser TEXT,country TEXT) WITH(connector='single_file',path='@OUTPUT@',format='json',type='sink');
INSERT INTO result SELECT session_id,canonical_id,tenant_id,to_char(start_time,'%Y-%m-%d %H:%M:%S%.3f') AS start_time,to_char(end_time,'%Y-%m-%d %H:%M:%S%.3f') AS end_time,duration_sec,event_count,array_sort(array_distinct(pages)) AS pages,event_types,device_type,browser,country FROM closed_sessions;
